package com.hms.branches;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="hospital_branches") public class HospitalBranch { @Id private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false,length=40) private String code; @Column(nullable=false,length=180) private String name; @Column(length=500) private String address; @Column(length=40) private String phone; @Column(nullable=false) private boolean active; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected HospitalBranch(){} public HospitalBranch(UUID tenantId,CreateBranchRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.code=r.code().trim().toUpperCase();this.name=r.name().trim();this.address=r.address();this.phone=r.phone();this.active=true;this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public String getCode(){return code;} public String getName(){return name;} public String getAddress(){return address;} public String getPhone(){return phone;} public boolean isActive(){return active;} }
